package com.amardokan.app.auth\n\nimport android.content.Context\nimport com.google.firebase.auth.FirebaseAuth\nimport com.google.firebase.auth.FirebaseUser\nimport com.google.firebase.firestore.FirebaseFirestore\nimport kotlinx.coroutines.tasks.await\nimport timber.log.Timber\n\nclass AuthManager(private val context: Context) {\n    private val firebaseAuth = FirebaseAuth.getInstance()\n    private val firestore = FirebaseFirestore.getInstance()\n\n    suspend fun loginWithPhoneNumber(phoneNumber: String): Result<Boolean> {\n        return try {\n            // In production, use Firebase Phone Auth\n            // For now, create user with email\n            val email = \"${phoneNumber.replace(\"+\", \"\")}@amardokan.app\"\n            val password = generateSecurePassword()\n            \n            firebaseAuth.createUserWithEmailAndPassword(email, password).await()\n            Timber.d(\"User created with phone: $phoneNumber\")\n            Result.success(true)\n        } catch (e: Exception) {\n            Timber.e(e, \"Phone login failed\")\n            Result.failure(e)\n        }\n    }\n\n    suspend fun loginWithGoogle(idToken: String): Result<Boolean> {\n        return try {\n            val credential = com.google.firebase.auth.GoogleAuthProvider.getCredential(idToken, null)\n            firebaseAuth.signInWithCredential(credential).await()\n            Timber.d(\"Google login successful\")\n            Result.success(true)\n        } catch (e: Exception) {\n            Timber.e(e, \"Google login failed\")\n            Result.failure(e)\n        }\n    }\n\n    suspend fun handlePostLoginRequest(\n        deviceId: String,\n        deviceName: String,\n        platform: String,\n        appVersion: String,\n        fcmToken: String,\n        osVersion: String\n    ): Result<String> {\n        return try {\n            val user = firebaseAuth.currentUser ?: throw Exception(\"User not authenticated\")\n            \n            // Call Cloud Function\n            val functions = com.google.firebase.functions.FirebaseFunctions.getInstance()\n            val data = hashMapOf(\n                \"device_id\" to deviceId,\n                \"device_name\" to deviceName,\n                \"platform\" to platform,\n                \"app_version\" to appVersion,\n                \"fcm_token\" to fcmToken,\n                \"os_version\" to osVersion\n            )\n            \n            val result = functions.getHttpsCallable(\"handleLogin\").call(data).await()\n            val resultMap = result.data as? Map<*, *>\n            val requestId = resultMap?.get(\"request_id\") as? String ?: \"\"\n            \n            Timber.d(\"Login request created: $requestId\")\n            Result.success(requestId)\n        } catch (e: Exception) {\n            Timber.e(e, \"Post-login request failed\")\n            Result.failure(e)\n        }\n    }\n\n    suspend fun checkLoginApprovalStatus(requestId: String): Result<String> {\n        return try {\n            val user = firebaseAuth.currentUser ?: throw Exception(\"User not authenticated\")\n            val shopId = getUserShopId(user.uid) ?: throw Exception(\"Shop ID not found\")\n            \n            val snapshot = firestore.collection(\"login_requests\")\n                .document(requestId)\n                .get()\n                .await()\n            \n            val status = snapshot.getString(\"status\") ?: \"pending\"\n            Timber.d(\"Login request status: $status\")\n            Result.success(status)\n        } catch (e: Exception) {\n            Timber.e(e, \"Status check failed\")\n            Result.failure(e)\n        }\n    }\n\n    suspend fun getUserShopId(uid: String): String? {\n        return try {\n            val snapshot = firestore.collection(\"users\")\n                .document(uid)\n                .get()\n                .await()\n            snapshot.getString(\"shop_id\")\n        } catch (e: Exception) {\n            Timber.e(e, \"Failed to get shop ID\")\n            null\n        }\n    }\n\n    suspend fun getUserRole(uid: String): String? {\n        return try {\n            val snapshot = firestore.collection(\"users\")\n                .document(uid)\n                .get()\n                .await()\n            snapshot.getString(\"role\")\n        } catch (e: Exception) {\n            Timber.e(e, \"Failed to get user role\")\n            null\n        }\n    }\n\n    fun getCurrentUser(): FirebaseUser? = firebaseAuth.currentUser\n\n    fun logout() {\n        firebaseAuth.signOut()\n        Timber.d(\"User logged out\")\n    }\n\n    private fun generateSecurePassword(): String {\n        val chars = \"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789!@#$%\"\n        return (1..16).map { chars.random() }.joinToString(\"\")\n    }\n}\n"}}]
